# Find the two main regions (they appear as separate blocks horizontally)
def find_horizontal_blocks(grid):
    """Find continuous horizontal blocks separated by columns of zeros"""
    blocks = []
    visited = set()
    h, w = len(grid), len(grid[0])

    def dfs(start_pos):
        stack = [start_pos]
        region = []
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            region.append((r, c))

            # Get value
            val = grid[r][c]
            if val != 0:
                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited:
                        if grid[nr][nc] == val or grid[nr][nc] > 0:  # Same color or any positive
                            stack.append((nr, nc))
        return region

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in visited:
                block = dfs((r, c))
                blocks.append(block)

    return blocks

