# Find connected components where connectivity is through same-valued neighbors only
def find_components_by_value(grid):
    """Find connected components where each component has uniform color"""
    components = []
    visited = set()
    h, w = len(grid), len(grid[0])

    def dfs(start_pos, val):
        stack = [start_pos]
        region = [start_pos]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))

            # Visit same-valued neighbors
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited:
                    if grid[nr][nc] == val:
                        stack.append((nr, nc))
        return region

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in visited:
                val = grid[r][c]
                comp = dfs((r, c), val)
                components.append(comp)

    return components

components = find_components_by_value(test_input)
print(f"Found {len(components)} monochromatic components")

# Group components by color into larger regions
def find_multicolored_regions(grid):
    """Find contiguous non-zero regions regardless of internal color"""
    regions = []
    visited = set()
