    def dfs(pos):
        stack = [pos]
        region = [pos]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited:
                    if grid[nr][nc] != 0:
                        stack.append((nr, nc))
        return region

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in visited:
                region = dfs((r, c))
                regions.append(region)

    return regions

