# Find vertical bands (columns with mostly zeros) to split grid into regions
def find_vertical_bands(grid):
    """Identify columns where most entries are zero"""
    h, w = len(grid), len(grid[0])
    band_threshold = 0.6  # Column is a band if >60% of its entries are zero

    bands = [True]  # Start with first column potentially part of region
    col_is_band = []

    for c in range(w):
        non_zero_count = sum(1 for r in range(h) if grid[r][c] != 0)
        band = non_zero_count / h < band_threshold
        col_is_band.append(band)

    # Merge adjacent bands into one band marker
    merged_bands = []
    i = 0
    while i < len(col_is_band):
        if col_is_band[i]:
            start = i
            while i < len(col_is_band) and col_is_band[i]:
                i += 1
            merged_bands.append((start, i-1))
        else:
            i += 1
    return merged_bands

